"""Accessible schematic containing only the three source-verified addresses."""
PLACES=[('main','vtuz','Главный корпус','Мира, 19',90,105),('radio','vtuz','Радиофак','Мира, 32',320,210),('nvk','nvk','Оформление проживания НВК','100-летия УрГУ, 6/2',610,145)]
MAP='<div class="tabs campus-tabs" role="group" aria-label="Выберите кампус"><button data-campus-choice="vtuz" aria-pressed="true">Втузгородок</button><button data-campus-choice="nvk" aria-pressed="false">Новокольцовский</button></div><div class="campus-explorer"><svg viewBox="0 0 900 420" role="group" aria-label="Условная схема кампусов. Без масштаба, не географическая карта."><rect width="900" height="420" rx="16" fill="#e9eddc"/><path d="M60 90h490M280 40v340M70 320h480M600 80v280" stroke="#fffef9" stroke-width="24"/><path d="M555 210h40" stroke="#07584b" stroke-width="3" stroke-dasharray="5 5"/>'
for key,campus,name,address,x,y in PLACES:
    short='Оформление НВК' if key=='nvk' else name
    MAP+=f'<a class="map-place" href="#campus-detail" data-map-place="{key}"'+(' aria-current="true"' if key=='main' else '')+f'><rect x="{x}" y="{y}" width="210" height="110" rx="12" fill="'+('#d5f64b' if key=='main' else '#f6f5ed')+f'" stroke="#07584b" stroke-width="2"/><text x="{x+16}" y="{y+38}" fill="#172321" font-size="16">{address}</text><text x="{x+16}" y="{y+72}" fill="#172321" font-size="13">{short}</text></a>'
MAP+='</svg><div><div class="campus-place-list" role="group" aria-label="Подтверждённые места">'
for key,campus,name,address,x,y in PLACES:MAP+=f'<button data-map-place="{key}" aria-pressed="'+('true' if key=='main' else 'false')+f'"><strong>{name}</strong><span>{address}</span></button>'
MAP+='</div><div id="campus-detail" class="campus-detail" aria-live="polite" tabindex="-1"><h3>Главный корпус</h3><p>Екатеринбург, улица Мира, 19.</p><p class="small">Адрес подтверждён. Вход и маршрут внутри здания уточняйте перед поездкой.</p></div></div></div><p class="small">Условная схема · без масштаба · не используется для навигации. Расстояния и время в пути не указаны.</p>'
